hudson.tasks.Shell.command:
#!/bin/sh set -eux
JENKINS_HOME=/var/jenkins_home BACKUP_DIR=$JENKINS_HOME/local_backup LOCAL=Asia/Taipei DATE=$(TZ=$LOCAL date +%Y%m%d_%H%M) ARCHIVE=jenkins_backup_$DATE.tar.gz ARCHIVE_PATH=$BACKUP_DIR/$ARCHIVE KEEP=${KEEP_COUNT}
mkdir -p $BACKUP_DIR cd $JENKINS_HOME tar -czf "$BACKUP_DIR/$ARCHIVE" \ jobs \ users \ secrets \ config.xml # (1) The size of the 'plugins' folder is too large (2) The plugin is intalled while building the docker image # plugins \ echo "Backup created: $BACKUP_DIR/$ARCHIVE" # The tar file exists in the 'jenkins space' # ===== 驗證備份檔（tar test）===== tar -tzf "$ARCHIVE_PATH" > /dev/null echo "Backup verification passed"
# ----- 上傳至雲端 ----- # 用瀏覽器登入一次 Google 帳號（產生 token）=> 設定 Google Drive(最重要，但只做一次): rclone.conf => 需存在在掛載點($JENKINS_HOME)的本機路徑裡 需認證取得token RCLONE_REMOTE=gdrive # rclone remote name RCLONE_PATH=backup # Google Drive 上的路徑 export RCLONE_CONFIG="$JENKINS_HOME/.config/rclone/rclone.conf" # 傳輸 rclone copy "$ARCHIVE_PATH" "$RCLONE_REMOTE:$RCLONE_PATH" -P # 驗證 #rclone md5sum "$ARCHIVE_PATH" #rclone md5sum "$RCLONE_REMOTE:$RCLONE_PATH/$ARCHIVE" LOCAL_MD5=$(rclone md5sum "$ARCHIVE_PATH" | awk '{print $1}') REMOTE_MD5=$(rclone md5sum "$RCLONE_REMOTE:$RCLONE_PATH/$ARCHIVE" | awk '{print $1}') if [ "$LOCAL_MD5" != "$REMOTE_MD5" ]; then echo "ERROR: MD5 mismatch!" exit 1 fi echo "Cloud upload verification passed" # ===== 清理舊備份（只留最新 KEEP 份）===== cd "$BACKUP_DIR" ls -1t jenkins_backup_*.tar.gz | tail -n +$((KEEP+1)) | xargs -r rm -f echo "Old backups cleaned, keeping latest $KEEP files" # ----- 雲端保留最新 N 份 ----- FILES=$(rclone lsf "$RCLONE_REMOTE:$RCLONE_PATH" --files-only | grep '^jenkins_backup_.*\.tar\.gz$') echo "$FILES" | sort -r | tail -n +$(($KEEP+1)) | while read -r f; do echo "Deleting old cloud backup: $f" rclone delete "$RCLONE_REMOTE:$RCLONE_PATH/$f" done
